COMMIT;

-- ----------------------------
-- Table structure for j_food_nutrition
-- ----------------------------
DROP TABLE IF EXISTS `j_food_nutrition`;
CREATE TABLE `j_food_nutrition` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `cate_id` int(11) DEFAULT '0',
  `food_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '食物名称',
  `alias_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '别名或俗名',
  `english_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '英文名称',
  `edible_part` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '食部(可食部分比例%)',
  `water` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '水分',
  `energy` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '能量',
  `protein` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '蛋白质',
  `fat` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脂肪',
  `cholesterol` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '胆固醇',
  `ash` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '灰分',
  `carbohydrate` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '碳水化合物',
  `dietary_fiber` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '总膳食纤维',
  `carotene` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '胡萝卜素',
  `vitamin_a` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维生素A',
  `vitamin_e` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'α-TE',
  `thiamin` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '硫胺素',
  `riboflavin` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '核黄素',
  `niacin` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '烟酸',
  `vitamin_c` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维生素C',
  `calcium` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '钙',
  `phosphorus` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '磷',
  `potassium` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '钾',
  `sodium` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '钠',
  `magnesium` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '镁',
  `iron` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '铁',
  `zinc` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '锌',
  `selenium` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '硒',
  `copper` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '铜',
  `manganese` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '锰',
  `iodine` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '碘',
  `sfa` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '饱和脂肪酸',
  `mufa` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单不饱和脂肪酸',
  `pufa` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '多不饱和脂肪酸',
  `fatty_acids_total` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脂肪酸合计',
  PRIMARY KEY (`id`),
  KEY `idx_food_name` (`food_name`),
  KEY `idx_english_name` (`english_name`)
) ENGINE=InnoDB AUTO_INCREMENT=1615 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='食物营养成分表';

